package com.braseiro.dnd5e;

import org.json.JSONArray;
import org.json.JSONObject;
import java.util.*;

/** Deterministic character-origin procedures from Tasha chapter 1. */
public final class TashaOriginRulesEngine {
    public static final String BOOK="Tasha's Cauldron of Everything";
    private TashaOriginRulesEngine(){}
    public static JSONObject descriptor(){JSONObject o=new JSONObject();try{o.put("id","tasha_origin_rules").put("book",BOOK).put("status","compiled_phase_1").put("auto_rolls",false).put("procedures",new JSONArray().put("tasha.origin.asi_reassign").put("tasha.origin.language_swap").put("tasha.origin.proficiency_swap").put("tasha.origin.custom_lineage"));}catch(Exception ignored){}return o;}
    public static JSONObject execute(String id,JSONObject in){JSONObject x=in==null?new JSONObject():in;if("tasha.origin.asi_reassign".equals(id))return asi(x);if("tasha.origin.language_swap".equals(id))return language(x);if("tasha.origin.proficiency_swap".equals(id))return proficiency(x);if("tasha.origin.custom_lineage".equals(id))return lineage(x);return blocked("unknown_tasha_origin_rule");}
    private static JSONObject asi(JSONObject in){JSONObject o=base(6);try{JSONArray bonuses=in.optJSONArray("bonuses"),targets=in.optJSONArray("target_abilities");if(bonuses==null||targets==null||bonuses.length()!=targets.length()||bonuses.length()==0)return blocked(o,"bonuses_and_target_abilities_same_length_required");Set<String> seen=new HashSet<>();JSONObject assigned=new JSONObject();for(int i=0;i<bonuses.length();i++){int b=bonuses.optInt(i,0);String a=norm(targets.optString(i));if(b<=0||!ability(a))return blocked(o,"invalid_bonus_or_ability");if(seen.contains(a))return blocked(o,"multiple_racial_increases_cannot_target_same_ability");seen.add(a);int current=in.optJSONObject("current_scores")!=null?in.optJSONObject("current_scores").optInt(a,0):0;if(current>0&&current+b>20)return blocked(o,"ability_score_cannot_exceed_20");assigned.put(a,b);}return o.put("valid",true).put("assigned_bonuses",assigned).put("ability_cap",20);}catch(Exception e){return blocked(o,"invalid_inputs");}}
    private static JSONObject language(JSONObject in){JSONObject o=base(6);try{String replacement=in.optString("replacement_language");boolean dm=in.optBoolean("dm_approved",false);JSONArray standard=new JSONArray();String[] langs={"Abissal","Anão","Celestial","Comum","Dialeto Obscuro","Diminuto","Dracônico","Élfico","Gigante","Gnômico","Goblin","Infernal","Orc","Primordial","Silvestre","Subcomum"};boolean listed=false;for(String l:langs){standard.put(l);if(norm(l).equals(norm(replacement)))listed=true;}return o.put("replacement_allowed",listed||dm).put("standard_replacements",standard).put("dm_can_adjust_campaign_language_list",true);}catch(Exception e){return blocked(o,"invalid_inputs");}}
    private static JSONObject proficiency(JSONObject in){JSONObject o=base(6);try{String from=norm(in.optString("from_type")),to=norm(in.optString("to_type"));boolean ok=false;if(any(from,"skill","pericia"))ok=any(to,"skill","pericia");else if(any(from,"armor","armadura"))ok=any(to,"simple weapon","arma simples","martial weapon","arma marcial","tool","ferramenta");else if(any(from,"simple weapon","arma simples"))ok=any(to,"simple weapon","arma simples","tool","ferramenta");else if(any(from,"martial weapon","arma marcial"))ok=any(to,"simple weapon","arma simples","martial weapon","arma marcial","tool","ferramenta");else if(any(from,"tool","ferramenta"))ok=any(to,"tool","ferramenta","simple weapon","arma simples");return o.put("swap_allowed",ok).put("from_type",from).put("to_type",to);}catch(Exception e){return blocked(o,"invalid_inputs");}}
    private static JSONObject lineage(JSONObject in){JSONObject o=base(7);try{String size=norm(in.optString("size")),ability=norm(in.optString("ability"));boolean dark=in.optBoolean("choose_darkvision",false),skill=in.optBoolean("choose_skill_proficiency",false);if(!(any(size,"small","pequeno")||any(size,"medium","medio")))return blocked(o,"size_small_or_medium_required");if(!ability(ability))return blocked(o,"valid_ability_required");if(dark==skill)return blocked(o,"choose_exactly_one_darkvision_or_skill_proficiency");if(!in.optBoolean("feat_prerequisites_met",false))return blocked(o,"chosen_feat_prerequisites_required");if(!in.optBoolean("extra_language_dm_approved",false))return blocked(o,"extra_language_requires_dm_approval");return o.put("creature_type","Humanoid").put("size",size).put("speed_feet",30).put("ability_increase",new JSONObject().put(ability,2)).put("feat_granted",true).put("darkvision_feet",dark?60:0).put("skill_proficiency_granted",skill).put("languages",new JSONArray().put("Common").put(in.optString("extra_language")));}catch(Exception e){return blocked(o,"invalid_inputs");}}
    private static JSONObject base(int page){JSONObject o=new JSONObject();try{o.put("book",BOOK).put("page",page).put("status","ok").put("auto_rolls",false);}catch(Exception ignored){}return o;}private static JSONObject blocked(String r){return blocked(base(0),r);}private static JSONObject blocked(JSONObject o,String r){try{o.put("status","blocked").put("requires_resolution",true).put("reason",r);}catch(Exception ignored){}return o;}
    private static String norm(String s){return s==null?"":java.text.Normalizer.normalize(s.toLowerCase(new Locale("pt","BR")),java.text.Normalizer.Form.NFD).replaceAll("\\p{M}+","").trim();}private static boolean any(String s,String... xs){for(String x:xs)if(s.equals(norm(x)))return true;return false;}private static boolean ability(String a){return any(a,"strength","forca","dexterity","destreza","constitution","constituicao","intelligence","inteligencia","wisdom","sabedoria","charisma","carisma");}
}
